const {chromium}=require('playwright'),fs=require('fs'),path=require('path'),assert=require('node:assert/strict');
(async()=>{const browser=await chromium.launch({headless:true});try{
 const p=await browser.newPage({viewport:{width:390,height:844}}),root=path.join(__dirname,'../web'),errors=[];p.on('pageerror',e=>errors.push(e.message));
 await p.goto('about:blank');await p.setContent('<main id="host"></main>');
 for(const file of ['00-core','05-primitives','48-chat','55-approvals','96-aion-recruiting'])await p.addStyleTag({content:fs.readFileSync(path.join(root,'css',file+'.css'),'utf8')});
 await p.evaluate(()=>{window.el=(tag,cls,text)=>{const e=document.createElement(tag);e.className=cls||'';e.textContent=text||'';return e;};window.emptyRow=text=>el('p','',text);window.fmtWhen=x=>x;window.showToast=x=>window.toast=x;window.recSel='cand/one';window.aionMode='recruiting';window.recCache={};window.candidate={id:recSel,stage:'new'};window.calls=[];window.mode='ok';window.operation=null;window.fetchJSONRetry=async(method,url,payload)=>{calls.push({method,url,payload});if(url.includes('/reconcile/')){window.recordedEntry={...draft,seq:2,status:'sent',draftSeq:1,operationId:'op-one',messageId:'fake-message',threadId:'fake-thread'};candidate.outreach=[{operations:['op-one']}];return {ok:true,text:async()=>JSON.stringify({entry:recordedEntry,view:{}})};}if(url.includes('/draft/'))return {ok:true,text:async()=>JSON.stringify({entry:{...draft,body:payload.body}})};if(mode==='refused')return {ok:false,text:async()=>JSON.stringify({readiness:{ready:false},error:'Fit gate changed'})};if(mode==='lost'){mode='ok';throw Error('Reply lost')};operation={record:{operationId:'op-one',status:'pending_approval',policy:'human_approval',arguments:{email:{from:'ben@aion.bio',to:draft.to,subject:draft.subject,body:draft.body}},input:{sourceRecord:{revision:'a'.repeat(64)}}},proposal:{id:'approval-one'}};return {ok:true,text:async()=>JSON.stringify({operationId:'op-one'})};};window.decisions=[];window.setSaveState=()=>{};window.loadFeed=()=>{};window.renderMarkdown=text=>el('pre','',text);window.fetch=async(url,opts={})=>{if(opts.method==='POST'){decisions.push(url);operation.record.status='succeeded';operation.record.result={messageId:'fake-message',threadId:'fake-thread'};}return {ok:true,json:async()=>({entries:window.recordedEntry?[draft,recordedEntry]:[draft],draftRevision:'a'.repeat(64),operations:operation?[operation]:[]})};};window.manifestOperationCard=item=>el('article','operation','Canonical '+item.record.status);window.renderAion=()=>document.getElementById('host').replaceChildren(recOutreachSection(candidate));window.draft={seq:1,status:'draft',kind:'direct',to:['candidate@example.test'],subject:'Reviewed subject',body:'Reviewed body'};});
 const source=fs.readFileSync(path.join(root,'js/96-aion-recruiting.js'),'utf8');await p.addScriptTag({content:source.slice(source.indexOf('let recOutreachProbe ='),source.indexOf('function recSection('))});await p.addScriptTag({content:source.slice(source.indexOf('function recSection('),source.indexOf('\n}',source.indexOf('function recSection('))+2)});
 const approvals=fs.readFileSync(path.join(root,'js/55-approvals.js'),'utf8');await p.addScriptTag({content:approvals.slice(approvals.indexOf('function manifestOperationCard('),approvals.indexOf('let manifestRevealTarget'))});const decisionStart=approvals.indexOf('async function postApprovalDecision(');await p.addScriptTag({content:approvals.slice(decisionStart,approvals.indexOf('\n}',decisionStart)+2)});
 await p.evaluate(()=>{recOutreachProbe={sendCapable:true,sender:'ben@aion.bio'};recOutreachLog={id:recSel,entries:[draft],draftRevision:'a'.repeat(64),operations:[]};renderAion();});
 assert.equal(await p.getByRole('button',{name:'send as',exact:false}).count(),0);
 await p.evaluate(()=>mode='refused');await p.getByRole('button',{name:'prepare approval',exact:true}).click();assert.equal(await p.evaluate(()=>toast),'Fit gate changed');assert.equal(await p.locator('.chat-operation').count(),0);
 await p.evaluate(()=>mode='lost');await p.getByRole('button',{name:'prepare approval',exact:true}).click();assert.equal(await p.evaluate(()=>toast),'Reply lost');
 await p.getByRole('button',{name:'prepare approval',exact:true}).click();await p.getByText('Review email',{exact:true}).waitFor();
 const calls=await p.evaluate(()=>window.calls);assert.deepEqual(calls.at(-1),calls.at(-2),'retry sends the exact reviewed revision');assert.ok(calls.every(c=>!c.url.includes('/send/')));
 await p.getByRole('button',{name:'Approve',exact:true}).click();await p.getByText('Email sent',{exact:true}).waitFor();assert.deepEqual(await p.evaluate(()=>decisions),['/api/spirits/approvals/approval-one/confirm']);
 // Recovery must refresh the enclosing recruiting actions, not just its email card.
 await p.evaluate(()=>{operation.record.status='partial';window.recoveryCalls=[];window.postJSONOk=async(url,body)=>{recoveryCalls.push({url,body});operation.record={...operation.record,status:'succeeded'};return {record:operation.record};};renderAion();});
 assert.equal(await p.getByRole('button',{name:'record sent outcome',exact:true}).count(),0);
 await p.getByRole('button',{name:'Check delivery',exact:true}).click();
 await p.getByRole('button',{name:'record sent outcome',exact:true}).waitFor();
 assert.deepEqual(await p.evaluate(()=>recoveryCalls),[{url:'/api/manifest/operations/op-one/email-reconcile',body:{}}]);
 assert.equal(await p.evaluate(()=>decisions.length),1,'recovery cannot approve or send again');
 await p.locator('textarea').evaluate(e=>e.value='Unsaved new text');await p.getByRole('button',{name:'view saved approval',exact:true}).click();assert.ok((await p.evaluate(()=>toast)).includes('Finish saving'));
 for(const width of [320,390,1440]){await p.setViewportSize({width,height:844});assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);}
 await p.getByRole('button',{name:'record sent outcome',exact:true}).click();await p.getByText('Sent outcome recorded in recruiting.',{exact:true}).waitFor();assert.equal(await p.getByRole('button',{name:'prepare approval',exact:true}).count(),0);assert.equal(await p.evaluate(()=>recOutreachCurrentDraft([{seq:1,status:'draft'},{seq:2,status:'draft'},{seq:3,status:'sent',draftSeq:1}]).seq),2);assert.equal(await p.evaluate(()=>decisions.length),1,'recording cannot approve or send again');
 await p.setViewportSize({width:390,height:844});await p.screenshot({path:'/tmp/manifest-outreach-approval-phone.png'});
 // Late candidate responses cannot replace the active candidate's approval set.
 await p.evaluate(()=>{window.fetch=()=>new Promise(resolve=>{window.releaseOld=()=>resolve({ok:true,json:async()=>({entries:[],operations:[]})})});window.oldLoad=recOutreachLoadLog('cand/old');});
 await p.evaluate(async()=>{window.fetch=async()=>({ok:true,json:async()=>({entries:[],operations:[]})});await recOutreachLoadLog('cand/new');releaseOld();await oldLoad;});assert.equal(await p.evaluate(()=>recOutreachLog.id),'cand/new');
 assert.deepEqual(errors,[]);console.log('Recruiting canonical approval preparation, refusal, lost-response retry, receipt refresh, unsaved edit guard and candidate isolation passed');
}finally{await browser.close()}})().catch(e=>{console.error(e);process.exitCode=1});
